"""Embed verified local screenshots in a standalone Korean user manual."""
from pathlib import Path
import base64
import html
import json
import re

ROOT = Path(__file__).resolve().parent
ASSETS = ROOT / "assets"
data = json.loads((ASSETS / "screens.json").read_text())
assert data.get("completed") and data.get("downloadsVerified")
assert not data["errors"], data["errors"]


def data_uri(filename):
    mime = "image/png" if filename.endswith(".png") else "image/jpeg"
    return "data:" + mime + ";base64," + base64.b64encode((ASSETS / filename).read_bytes()).decode()


names = set()
for scene in data["scenes"]:
    names.add(scene["image"])
    for action in scene["actions"]:
        names.update(x for x in (action["before"], action["after"]) if x)
data["images"] = {name: data_uri(name) for name in sorted(names)}
sample = data_uri("sample_test_sheet.png")
text_steps = []
for scene in data["scenes"]:
    values = "".join(
        "<li><b>" + html.escape(a["label"]) + "</b><span>" + html.escape(str(a.get("display", a["value"]))) + "</span></li>"
        for a in scene["actions"]
    )
    notes = "".join("<li>" + html.escape(n) + "</li>" for n in scene["notes"])
    text_steps.append(
        f'<article class="text-step" id="text-step-{scene["number"]}">'
        f'<span class="text-no">{scene["number"]:02}</span><div><h3>{html.escape(scene["title"])}</h3>'
        f'<p>{html.escape(scene["lead"])}</p><ul class="text-values">{values}</ul>'
        f'<ul class="text-notes">{notes}</ul><button class="text-open" data-scene="{scene["number"]-1}">이 장면 보기 ↗</button></div></article>'
    )

